const script = String.raw`#!/usr/bin/env python3
"""Export Claude Desktop (local agent / Claude Code) session transcripts to Markdown."""
import json, glob, os, sys, datetime

OUT = os.path.expanduser("~/claude-desktop-export")
SRC = os.path.expanduser("~/.claude/projects")
META = os.path.expanduser("~/.config/Claude-3p/claude-code-sessions")

def load_meta():
    m = {}
    for f in glob.glob(os.path.join(META, "*", "*", "local_*.json")):
        try:
            d = json.load(open(f))
        except Exception:
            continue
        m[d.get("cliSessionId") or d.get("sessionId")] = d
    return m

def text_of(content):
    if isinstance(content, str):
        return content
    out = []
    for b in content or []:
        if not isinstance(b, dict):
            continue
        t = b.get("type")
        if t == "text":
            out.append(b.get("text", ""))
        elif t == "thinking":
            out.append("> [thinking] " + b.get("thinking", "")[:4000])
        elif t == "tool_use":
            out.append("**Tool: %s**\n\n~~~json\n%s\n~~~" % (b.get("name"), json.dumps(b.get("input"), ensure_ascii=False, indent=1)[:3000]))
        elif t == "tool_result":
            c = b.get("content")
            s = c if isinstance(c, str) else text_of(c)
            out.append("<details><summary>tool_result</summary>\n\n~~~\n%s\n~~~\n</details>" % (s[:3000],))
        elif t == "image":
            out.append("[image]")
    return "\n\n".join(x for x in out if x)

def fmt_ts(ts):
    if not ts:
        return ""
    try:
        return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone().strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return ts

def main():
    meta = load_meta()
    os.makedirs(OUT, exist_ok=True)
    rows = []
    for f in sorted(glob.glob(os.path.join(SRC, "*", "*.jsonl"))):
        sid = os.path.basename(f)[:-6]
        proj = os.path.basename(os.path.dirname(f))
        m = meta.get(sid, {})
        title = m.get("title") or ""
        lines = []
        first_user = ""
        n_msg = 0
        start = end = None
        for raw in open(f, encoding="utf-8"):
            try:
                d = json.loads(raw)
            except Exception:
                continue
            t = d.get("type")
            if t not in ("user", "assistant"):
                continue
            msg = d.get("message") or {}
            body = text_of(msg.get("content"))
            if not body.strip():
                continue
            role = msg.get("role") or t
            who = "User" if role == "user" else "Assistant"
            if d.get("isSidechain"):
                who += " (subagent)"
            ts = fmt_ts(d.get("timestamp"))
            start = start or ts
            end = ts or end
            n_msg += 1
            if role == "user" and not first_user and not d.get("isSidechain") and isinstance(msg.get("content"), str):
                first_user = body.strip()
            lines.append("### %s  ·  %s\n\n%s\n" % (who, ts, body))
        if not lines:
            continue
        label = title or first_user.replace("\n", " ")[:50] or sid[:8]
        slug = "".join(ch if ch.isalnum() or ch in "-_" else "-" for ch in label)[:40].strip("-")
        fname = "%s_%s.md" % (start[:10] if start else "undated", slug or sid[:8])
        path = os.path.join(OUT, fname)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write("# %s\n\n" % label)
            fh.write("- session: `%s`\n- project: `%s`\n- cwd: `%s`\n" % (sid, proj, m.get("originCwd") or m.get("cwd") or ""))
            fh.write("- time: %s → %s\n- messages: %d\n\n---\n\n" % (start, end, n_msg))
            fh.write("\n".join(lines))
        rows.append((start, label, n_msg, os.path.getsize(path), os.path.basename(path)))
    rows.sort(reverse=True)
    with open(os.path.join(OUT, "INDEX.md"), "w", encoding="utf-8") as fh:
        fh.write("# Claude Desktop 会话导出索引\n\n共 %d 个会话\n\n| 时间 | 标题 | 消息数 | 文件 |\n|---|---|---|---|\n" % len(rows))
        for start, label, n, size, fn in rows:
            fh.write("| %s | %s | %d | [%s](%s) |\n" % (start, label, n, fn, fn))
    print("exported %d sessions -> %s" % (len(rows), OUT))
    for r in rows:
        print(" %s  %-40s %4d msgs  %6.1fK" % (r[0], r[1][:40], r[2], r[3]/1024))

if __name__ == "__main__":
    main()
`;
